EnterEditMode();
// Verify CenterListView and EndListView receive the same edit-state transition as StartListView.
ExitEditMode();
// Persist the complete edit transaction, then ensure the next entry snapshots the persisted center/end bands.

var (start, center, end) = GetActiveBands();
_settings = WithActiveBands(
    MergeBandSettings(start, latest, pending),
    MergeBandSettings(center, latest, pending),
    MergeBandSettings(end, latest, pending));
// Keep the three lists coherent with the collections used by the next edit session.

foreach (var section in new[] { Start, Center, End })
{
    AddNewBand(section);
    SaveBandOrder();
    SnapshotBandOrder();
    RemoveBand(section);
    SaveBandOrder();
    AssertSectionIsEmpty(section);
}
